    21	    public FxQuote quote(String currency, LocalDate date) {
    22	        String pair = CurrencyPairs.pairOf(currency);
    23	        return cache.computeIfAbsent(pair + "@" + date, k -> {
    24	            vendorCalls++;
    25	            return FxqClient.parse(client.rate(pair, date));
    26	        });
    27	    }
