     5	/** Tiny assertion runner (no external test framework available on the batch host). */
     6	final class TestSupport {
     7	    private final String suite;
     8	    private final List<String> failures = new ArrayList<>();
     9	    private int passed;
    10	
    11	    TestSupport(String suite) {
    12	        this.suite = suite;
    13	    }
    14	
    15	    interface Body { void run() throws Exception; }
    16	
    17	    void test(String name, Body body) {
    18	        try {
    19	            body.run();
    20	            passed++;
    21	            System.out.println("ok   - " + name);
    22	        } catch (AssertionError | Exception e) {
    23	            failures.add(name + ": " + e.getMessage());
    24	            System.out.println("FAIL - " + name + ": " + e.getMessage());
    25	        }
    26	    }
    27	
    28	    static void eq(Object expected, Object actual, String msg) {
    29	        if (!Objects.equals(expected, actual)) {
    30	            throw new AssertionError(msg + " (expected " + expected + ", got " + actual + ")");
    31	        }
    32	    }
    33	
    34	    static void check(boolean cond, String msg) {
    35	        if (!cond) throw new AssertionError(msg);
    36	    }
    37	
    38	    void finish() {
    39	        System.out.printf("%s: %d passed, %d failed%n", suite, passed, failures.size());
    40	        if (!failures.isEmpty()) System.exit(1);
    41	    }
    42	}

