import csv, subprocess, datetime as dt
from decimal import Decimal, ROUND_HALF_UP
from collections import defaultdict
F='vendor/bin/fxq'
def rate(pair,d,src):
    out=subprocess.run([F,'rate',pair,d,'--src',str(src)],capture_output=True,text=True).stdout.strip().split()
    return Decimal(out[2])
units={'USD':1,'EUR':1,'JPY':100,'CNY':1}
txns=list(csv.DictReader(open('fixtures/transactions.csv')))
stm={(r['date'],r['partner_id']):int(r['gross_krw']) for r in csv.DictReader(open('fixtures/partner-statement.csv'))}
dates=['2026-10-0%d'%i for i in range(1,6)]
# group txns by KST date, partner
grp=defaultdict(list)
for t in txns:
    a=dt.datetime.fromisoformat(t['approved_at'].replace('Z','+00:00')).astimezone(dt.timezone(dt.timedelta(hours=9)))
    grp[(a.date().isoformat(),t['partner_id'])].append(t)
for d in dates:
    for src in range(4):
        rates={c:rate(c+'KRW',d,src) for c in units}
        res=[]
        for (dd,p),ts in sorted(grp.items()):
            if dd!=d or (p=='P-1004'): continue
            gross=0
            for t in ts:
                amt=Decimal(t['amount'])*(-1 if t['type']=='REFUND' else 1)
                gross+=int((amt*rates[t['currency']]/units[t['currency']]).quantize(Decimal(1),ROUND_HALF_UP))
            ok = 'OK' if stm.get((dd,p))==gross else 'x'
            res.append(f"{p}:{gross}/{stm.get((dd,p))}{ok}")
        print(d,'src',src,' '.join(f"{c}={rates[c]}" for c in units),' | ',' '.join(res))
EOF

